#!/usr/bin/env python3
"""Helper script for third_party/envoy-gateway/update.sh to process Envoy Gateway manifests."""

import sys

import yaml

_EG_CRD_HEADER = """# Generated by update.sh. DO NOT EDIT!
# ---------------------------------------------------------
# Envoy Gateway Custom Resource Definitions (CRDs)
# ---------------------------------------------------------
"""

_EG_SYSTEM_HEADER = """{{- if eq .Values.use_gateway "true" }}
# Generated by update.sh. DO NOT EDIT!
# ---------------------------------------------------------
# Envoy Gateway System Manifests
# ---------------------------------------------------------
"""

_EG_SYSTEM_FOOTER = "\n{{- end }}\n"


def _parse_manifests(install_file: str) -> tuple[list[str], list[str]]:
  """Parses the upstream install.yaml and splits into CRDs and system docs.

  Args:
    install_file: Path to the upstream install.yaml file.

  Returns:
    A tuple of (eg_crds, system_docs) where:
      eg_crds: List of string YAML documents for Envoy Gateway CRDs.
      system_docs: List of string YAML documents for Envoy Gateway system
        manifests.
  """
  with open(install_file, "r", encoding="utf-8") as f:
    raw_content = f.read()

  docs_text = raw_content.split("\n---\n")
  eg_crds = []
  system_docs = []

  for doc_str in docs_text:
    cleaned = doc_str.strip()
    if not cleaned:
      continue
    try:
      doc_obj = yaml.safe_load(cleaned)
    except yaml.YAMLError:
      system_docs.append(cleaned)
      continue

    if not doc_obj or not isinstance(doc_obj, dict):
      continue

    kind = doc_obj.get("kind")
    if kind == "CustomResourceDefinition":
      spec = doc_obj.get("spec") or {}
      group = spec.get("group", "")
      # Only include Envoy Gateway proprietary CRDs (*.gateway.envoyproxy.io).
      if group.endswith("gateway.envoyproxy.io"):
        eg_crds.append(cleaned)
    else:
      system_docs.append(cleaned)

  return eg_crds, system_docs


def _write_crds(crds: list[str], dst: str) -> None:
  """Writes Envoy Gateway CRDs to the destination file.

  Args:
    crds: List of CRD YAML documents.
    dst: Path to the output file.
  """
  with open(dst, "w", encoding="utf-8") as f:
    f.write(_EG_CRD_HEADER + "\n---\n".join(crds) + "\n")


def _write_system_manifests(docs: list[str], dst: str) -> None:
  """Writes Envoy Gateway system manifests wrapped with Helm condition.

  Args:
    docs: List of system manifest YAML documents.
    dst: Path to the output file.
  """
  with open(dst, "w", encoding="utf-8") as f:
    f.write(_EG_SYSTEM_HEADER + "\n---\n".join(docs) + _EG_SYSTEM_FOOTER)


def process_envoy_gateway(
    install_file: str, eg_crds_dst: str, eg_manifest_dst: str
) -> None:
  """Processes Envoy Gateway manifests.

  Args:
    install_file: Path to the upstream install.yaml file.
    eg_crds_dst: Output path for Envoy Gateway CRDs.
    eg_manifest_dst: Output path for Envoy Gateway controller manifests.
  """
  eg_crds, system_docs = _parse_manifests(install_file)
  _write_crds(eg_crds, eg_crds_dst)
  _write_system_manifests(system_docs, eg_manifest_dst)

  print(f"Successfully processed:\n  - {eg_crds_dst}\n  - {eg_manifest_dst}")


def main() -> None:
  if len(sys.argv) < 4:
    print(
        f"Usage: {sys.argv[0]} <install_file> <eg_crds_dst> <eg_manifest_dst>",
        file=sys.stderr,
    )
    sys.exit(1)
  process_envoy_gateway(sys.argv[1], sys.argv[2], sys.argv[3])


if __name__ == "__main__":
  main()
